def esc(x):return html.escape(str(x),quote=True)
def icon(group):return '<svg viewBox="0 0 26 26" aria-hidden="true">'+ICONS[GROUP_SLUGS[group]]+'</svg>'
LOGO='<svg viewBox="0 0 36 36" aria-hidden="true"><circle cx="18" cy="18" r="14" stroke="#af5636" fill="none"/><circle cx="18" cy="18" r="10" fill="#af5636"/><path d="M18 7v22M7 18h22" stroke="#f8f7f2" stroke-opacity=".35"/></svg>'
def header():return '<header class="site-header"><a class="brand" href="/" aria-label="Open STEM Lab home">'+LOGO+'<span>openstemlab<em>.</em></span></a><nav class="header-links" aria-label="Main navigation"><a href="/experiments/">Search experiments</a><a href="/#subjects">Browse subjects</a><a href="/#how-it-works">How it works</a><a class="nav-cta" href="'+EXPERIMENT+'">Enter the physics lab ↗</a></nav></header>'
def footer():return '<footer class="site-footer"><span>Open STEM Lab · Free to explore. Built for understanding.</span><nav aria-label="Footer"><a href="/#subjects">Subjects</a><a href="/experiments/">Search experiments</a><a href="/sitemap.xml">Sitemap</a><a href="/openstemlab-source.zip" download>Download source</a></nav></footer>'
def head(path,title,desc,base,indexable):
 structured={'@context':'https://schema.org','@type':'WebPage','name':title,'description':desc,'url':base+path,'isPartOf':{'@type':'WebSite','name':'Open STEM Lab','url':base+'/'},'inLanguage':'en'}
 return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+esc(title)+'</title><meta name="description" content="'+esc(desc)+'"><meta name="robots" content="'+('index,follow' if indexable else 'noindex,follow')+'"><link rel="canonical" href="'+base+path+'"><meta name="theme-color" content="#f8f7f2"><meta property="og:title" content="'+esc(title)+'"><meta property="og:description" content="'+esc(desc)+'"><meta property="og:url" content="'+base+path+'"><meta property="og:type" content="website"><link rel="stylesheet" href="/catalog.css"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@400;500;600;700;800&display=swap" rel="stylesheet"><script type="application/ld+json">'+json.dumps(structured)+'</script></head>'
def how_it_works():
 steps=[('01','Understand the idea','Start with the theory. Open the supporting concepts whenever you need a deeper explanation.'),('02','Explore the model','Change one variable, predict what will happen, and observe the response.'),('03','Practise the method','Follow a procedure, take measurements, and learn why each step matters.'),('04','Explain your evidence','Work through tables, graphs, calculations and a complete example report.')]
 return '<section class="learn-path" id="how-it-works"><span class="eyebrow">A COMPLETE LEARNING JOURNEY</span><h2>From “what?” to “now I understand.”</h2><div class="path-grid">'+''.join('<article class="path-step"><span>'+n+'</span><h3>'+title+'</h3><p>'+desc+'</p></article>' for n,title,desc in steps)+'</div></section>'
def build_catalog(out,base,production):
 db=sqlite3.connect(ROOT/'data/catalog.sqlite3');db.row_factory=sqlite3.Row
 live_experiments=[dict(r) for r in db.execute("SELECT * FROM experiments WHERE status='live' ORDER BY id")]
 subjects=[dict(r) for r in db.execute("SELECT * FROM subjects WHERE selection_status='retain' ORDER BY CASE WHEN slug='physics' THEN 0 ELSE 1 END,category,name")];deferred=db.execute("SELECT count(*) FROM subjects WHERE selection_status='conditional'").fetchone()[0]
 for s in subjects:s['examples']=json.loads(s['example_topics_json'])
 db.close()
 from build_search import experiment_index,search_section,build_directory
 lab_index=experiment_index(live_experiments)
 directory_path=build_directory(out,base,production,lab_index,subjects,head,header,footer)
 # A deliberately explicit public projection: no books, ISBNs or source URLs.
 public=[{k:s[k] for k in ['slug','name','category','display_mode','content_status']}|{'topics':s['examples'],'experiment_count':len([e for e in live_experiments if e['subject_id']==s['id']])} for s in subjects]
 (out/'catalog.json').write_text(json.dumps(public,ensure_ascii=False))
 for asset in ['catalog.css','catalog.js']:(out/asset).write_text((ROOT/'content'/asset).read_text())
 cards=''
 for s in subjects:
  count_for_s=len([e for e in live_experiments if e['subject_id']==s['id']])
  group=GROUP_SLUGS[s['category']];tint,accent=ACCENTS[group];topics=s['examples'][:3];available=count_for_s>0
  search=' '.join([s['name'],s['category'],s['display_mode']]+s['examples']).lower()
  cards+='<a class="subject-card" href="/subjects/'+s['slug']+'/" data-group="'+group+'" data-search="'+esc(search)+'" style="--tint:'+tint+';--accent:'+accent+'"><div class="card-top"><span class="subject-icon">'+icon(s['category'])+'</span><span class="type-pill">'+esc(s['display_mode'])+'</span></div><h3>'+esc(s['name'])+'</h3><p>'+esc(' · '.join(topics))+'</p><div class="card-footer"><span'+(' class="available"><i class="live-dot"></i> '+str(count_for_s)+' experiments ready' if available else '>Collection in preparation')+'</span><b aria-hidden="true">↗</b></div></a>'
 hero_svg='''<svg viewBox="0 0 450 235" role="img" aria-label="Illustration of photons reaching a metal surface and electrons moving toward a collector"><defs><pattern id="g" width="25" height="25" patternUnits="userSpaceOnUse"><path d="M25 0H0V25" fill="none" stroke="#ffffff" stroke-opacity=".04"/></pattern></defs><rect width="450" height="235" fill="url(#g)"/><path d="M12 110L140 55V184L12 159Z" fill="#c4b8e7" opacity=".08"/><rect x="140" y="42" width="14" height="153" rx="3" fill="#a5bda0"/><rect x="366" y="42" width="10" height="153" rx="3" fill="#718e7e"/><path d="M66 85h12m15 25h12m-66 32h12m49 24h12" stroke="#c7b9ed" stroke-width="2"/><g fill="#c7b9ed"><circle cx="85" cy="85" r="4"/><circle cx="112" cy="110" r="4"/><circle cx="58" cy="142" r="4"/><circle cx="119" cy="166" r="4"/></g><g fill="#d0dfa7"><circle cx="180" cy="75" r="3"/><circle cx="234" cy="130" r="3"/><circle cx="285" cy="101" r="3"/><circle cx="333" cy="162" r="3"/></g><path d="M180 75h26m28 55h26m25-29h26m22 61h20" stroke="#d0dfa7" stroke-opacity=".3"/><text x="148" y="221" text-anchor="middle" fill="#91a88f" font-size="9" letter-spacing="1">METAL SURFACE</text><text x="371" y="221" text-anchor="middle" fill="#91a88f" font-size="9" letter-spacing="1">COLLECTOR</text><text x="248" y="30" fill="#bacb9d" text-anchor="middle" font-size="11">hf = φ + Kmax</text></svg>'''
 home=head('/','Open STEM Lab | Free Virtual Experiments & Practical Learning','Explore university subjects through theory, simulations, practical methods and worked reports. Start with the interactive photoelectric effect experiment.',base,production)+'<body><div class="wrap">'+header()+'''<main><section class="hero"><div class="hero-copy"><span class="eyebrow">CURIOSITY BELONGS IN EVERY SUBJECT</span><h1>A place to learn.<br>A space to <em>experiment.</em></h1><p>Understand the theory. See it in action. Practise every step. Your open laboratory for university science, engineering and practical discovery.</p><div class="actions"><a class="primary" href="#subjects">Explore the subjects ↓</a><a class="secondary" href="'''+EXPERIMENT+'''">Try a live experiment ↗</a></div><div class="hero-note"><i></i> Free learning · No account needed</div></div><div class="hero-lab"><div class="lab-top"><span><i class="live-dot"></i> ON THE WORKBENCH</span><span>PHYSICS / 01</span></div>'''+hero_svg+'''<div class="lab-caption"><div><small>LIGHT & MATTER</small><h3>The photoelectric effect</h3></div><a href="'''+EXPERIMENT+'''" aria-label="Open the photoelectric effect experiment">↗</a></div></div></section><div class="stats"><div><strong>'''+str(len(subjects))+'''</strong><span>subject collections selected</span></div><div><strong>'''+str(len(live_experiments)).zfill(2)+'''</strong><span>complete experiments available</span></div><div><strong>04</strong><span>stages, from theory to results</span></div></div><section id="subjects"><div class="catalog-heading"><div><span class="eyebrow">FIND YOUR FIELD</span><h2>Where will your curiosity take you?</h2></div><label class="search"><span aria-hidden="true">⌕</span><input id="subjectSearch" type="search" placeholder="Search a subject or lab topic…" aria-label="Search subjects and laboratory topics"></label></div><div class="filters" role="group" aria-label="Filter subjects"><button class="filter active" data-filter="all" aria-pressed="true">All subjects</button>'''+''.join('<button class="filter" data-filter="'+GROUP_SLUGS[g]+'" aria-pressed="false">'+esc(g)+'</button>' for g in GROUPS)+'''</div><div class="catalog-status"><span id="resultCount" role="status" aria-live="polite">'''+str(len(subjects))+''' subjects</span><span>BENCH · COMPUTATIONAL · FIELD · BEHAVIORAL</span></div><div class="catalog-grid">'''+cards+'''</div><div id="emptyCatalog" class="catalog-empty" hidden><h3>No matching subjects yet.</h3><p>Try a broader topic, or browse all the collections.</p><button id="clearSearch" class="primary">Clear search & filters</button></div><div class="scope-note"><strong>A growing laboratory, with a clear starting point.</strong>Practical lessons are available in Physics, Computer Science, Chemistry, Mathematics, Statistics &amp; Probability, Aerospace &amp; Aeronautical Engineering, Agricultural Engineering, Biomedical Engineering, Chemical &amp; Process Engineering, Civil Engineering, Electrical &amp; Electronics Engineering, Electronics &amp; Communication, Mechanical Engineering, Textile Engineering, Archaeology, Geography, Psychology, Agriculture &amp; Forestry, Basic Medical Sciences, and Biological Sciences. Browse the active collections for the experiments available now. The other subject pages outline practical topics for future lessons; they do not yet contain working simulations. Specialist clinical and interdisciplinary tracks remain outside this first collection while their teaching scope is defined.</div></section>'''+how_it_works()+'</main>'+footer()+'</div><script src="/catalog.js"></script></body></html>'
 home=home.replace('<section id="subjects">',search_section(lab_index,subjects,prefix='experiment-search')+'<section id="subjects">').replace('<script src="/catalog.js">','<script src="/lab-search.js"></script><script src="/catalog.js">')
 (out/'index.html').write_text(home)
 sitemap=['/',directory_path]
 for s in subjects:
  path='/subjects/'+s['slug']+'/'
  count_for_s=len([e for e in live_experiments if e['subject_id']==s['id']])
  live=count_for_s>0
  if s['slug']=='physics':s['examples']=['Photoelectric effect','Oscillations and rotational inertia','Elasticity and fluid viscosity','Geometrical optics']
  elif s['slug']=='computer-science':s['examples']=['Search algorithms and complexity','Sorting algorithm timing','Recursion exploration','Stack and queue operations']
  elif s['slug']=='chemistry':s['examples']=['Precision density and analytical measurement','Thermochemistry and calorimetry','Reaction kinetics and rate laws','Acid-base equilibria and titrations']
  elif s['slug']=='mathematics':s['examples']=['Numerical analysis and root-finding','Numerical integration and differential equations','Linear algebra and matrix decompositions','Interpolation, Fourier analysis and dynamical systems']
  elif s['slug']=='statistics-probability':s['examples']=['Descriptive statistics and sampling distributions','Discrete and continuous probability distributions','Statistical hypothesis testing and ANOVA','Linear regression and Bayesian inference']
  elif s['slug']=='aerospace-aeronautical-engineering':s['examples']=['Subsonic aerodynamics and wind tunnel testing','Compressible flow and shock wave dynamics','Aircraft flight mechanics and stability','Aerospace propulsion and orbital mechanics']
  elif s['slug']=='agricultural-engineering':s['examples']=['Farm machinery and tractor power mechanics','Soil, water and irrigation engineering','Post-harvest crop processing and storage','Agricultural structures and renewable bioenergy']
  elif s['slug']=='biomedical-engineering':s['examples']=['Bioinstrumentation and physiological sensors','Biosignal processing, ECG and pulse oximetry','Orthopaedic biomechanics and biomaterials','Cardiovascular hemodynamics and medical devices']
  elif s['slug']=='chemical-process-engineering':s['examples']=['Fluid mechanics, flow metering and packed beds','Heat transfer, exchangers and evaporation','Mass transfer, distillation and absorption','Reaction kinetics, CSTR, PFR and catalysis','Process thermodynamics, VLE and calorimetry','Process dynamics, automatic control and filtration']
  elif s['slug']=='civil-engineering':s['examples']=['Structural materials and concrete technology','Mechanics of materials and structural analysis','Geotechnical and foundation engineering','Hydraulics, water resources and environmental engineering','Transportation, highway and pavement engineering','Surveying, geomatics and structural dynamics']
  elif s['slug']=='electrical-electronics-engineering':s['examples']=['DC and AC circuit analysis & network theorems','Analog electronics, op-amps & semiconductor devices','Digital electronics, counters & microprocessors','Electrical machines, transformers & induction motors','Power systems, protection relays & renewable energy','Control systems, power electronics & instrumentation']
  elif s['slug']=='electronics-communication':s['examples']=['Analog modulation & superheterodyne systems','Pulse modulation & digital baseband','Digital passband modulation (BPSK, QPSK, QAM)','Antennas, microwave propagation & RF','Optical fiber communication & optoelectronics','Digital signal processing & information theory']
  elif s['slug']=='mechanical-engineering':s['examples']=['Solid mechanics & materials testing','Fluid mechanics & hydraulic machinery','Thermodynamics & heat transfer','Dynamics, kinematics & mechanical vibrations','Machine design, tribology & metrology','Mechatronics, controls & industrial HVAC']
  elif s['slug']=='textile-engineering':s['examples']=['Yarn manufacturing & fiber science','Fabric manufacturing & mechanics','Textile wet processing & dyeing','Fabric comfort & physical testing','Textile tribology & durability','Technical textiles & color science']
  elif s['slug']=='archaeology':s['examples']=['Site-grid & geophysics survey','Lithic technology & petrography','Pyrotechnology & archaeomagnetism','Bioarchaeology & paleodiet isotopes','Geoarchaeology & micromorphology']
  elif s['slug']=='geography':s['examples']=['Fluvial geomorphology & hydraulics','Meteorology & microclimatology','Biogeography & soil hydrology','Coastal morphodynamics & shoaling','Spatial analysis & remote sensing']
  elif s['slug']=='psychology':s['examples']=['Cognitive psychology & psychophysics','Memory, attention & executive function','Learning & behavioral decision making','Physiological & neuropsychological measurement','Social & differential psychology']
  elif s['slug']=='agriculture-forestry':s['examples']=['Agronomy, crop physiology & seed science','Soil science & plant nutrition','Irrigation & agrohydrology','Plant pathology & crop protection','Silviculture & forest mensuration']
  elif s['slug']=='basic-medical-sciences':s['examples']=['Medical hematology & hemorheology','Cardiovascular & hemodynamic physiology','Neurophysiology & neuromuscular function','Pulmonary mechanics & gas exchange','Renal physiology & clinical biochemistry','Histopathology & preclinical pharmacology']
  elif s['slug']=='biological-sciences':s['examples']=['Cell biology & biomembrane transport','Enzymology & cellular metabolism','Molecular biology & genetics','Microbiology & microbial physiology','Plant physiology & ecology']
  desc='Explore '+s['name']+' practical learning: '+', '.join(s['examples'][:3])+'.'
  body=head(path,s['name']+' Laboratory & Practical Learning | Open STEM Lab',desc,base,production and live)+'<body><div class="wrap">'+header()+'<main><div class="breadcrumb"><a href="/">Home</a> / <a href="/#subjects">Subjects</a> / '+esc(s['name'])+'</div><section class="subject-hero"><span class="eyebrow">'+esc(s['category'].upper())+'</span><h1>'+esc(s['name'])+'</h1><p>'+esc(GROUP_INTRO[s['category']])+' This collection focuses on '+esc(', '.join(s['examples'][:3]).lower())+'.</p><div class="subject-badges"><span class="type-pill">'+esc(s['display_mode'])+'</span><span class="type-pill">'+(str(count_for_s)+' experiments available' if live else 'Collection in preparation')+'</span></div></section>'
  body+=search_section(lab_index,subjects,scope=s['slug'],heading='Find a lab in '+s['name'],prefix='department-labs')
  if live:sitemap.append(path)
  else:body+='<div class="scope-note"><strong>This collection is being prepared.</strong>Planned topics below are not yet working experiments.</div>'
  body+='<h2 class="subsection-title">Practical topics to explore</h2><p class="section-intro">Each future lesson will connect its central idea with an interactive model, a method for investigation and a clear explanation of the evidence.</p><div class="topic-grid">'
  future_topics=['Optical interference and diffraction','Electrical measurements and circuits','Thermal properties and calorimetry'] if s['slug']=='physics' else ['Sorting algorithm timing and comparisons','Recursion exploration and call stack analysis','Stack and queue operations'] if s['slug']=='computer-science' else ['Stoichiometry and precipitation','Thermochemistry and Hess\'s law','Chemical kinetics and rate laws'] if s['slug']=='chemistry' else ['Root-finding and nonlinear equations','Linear systems and matrix decompositions','Numerical integration and ODE initial value problems'] if s['slug']=='mathematics' else ['Descriptive statistics and sampling distributions','Probability distributions and stochastic processes','Parametric and non-parametric hypothesis testing'] if s['slug']=='statistics-probability' else ['Subsonic aerodynamics and boundary layers','Supersonic shock waves and expansion fans','Aircraft longitudinal and lateral flight stability','Rocket propulsion, gas turbines and orbital mechanics'] if s['slug']=='aerospace-aeronautical-engineering' else ['Tractor mechanics and tillage dynamics','Irrigation hydraulics and infiltration kinetics','Thin-layer drying and grain processing','Greenhouse environmental control and renewable bioenergy'] if s['slug']=='agricultural-engineering' else ['Bioinstrumentation and clinical front-ends','Biosignal processing and electrophysiology','Biomechanics and orthopaedic biomaterials','Cardiovascular hemodynamics and medical devices'] if s['slug']=='biomedical-engineering' else ['Fluid mechanics and transport phenomena','Heat transfer and thermal unit operations','Mass transfer, distillation and extraction','Chemical reaction engineering and catalysis','Thermodynamics, phase equilibria and solutions','Process dynamics, automatic control and separations'] if s['slug']=='chemical-process-engineering' else ['Structural materials and concrete technology','Mechanics of materials and structural analysis','Geotechnical and foundation engineering','Hydraulics, water resources and environmental engineering','Transportation, highway and pavement engineering','Surveying, geomatics and structural dynamics'] if s['slug']=='civil-engineering' else ['DC and AC network theorems','Operational amplifiers and semiconductor dynamics','Digital logic design and microprocessors','Electrical machines and electromechanics','Power transmission, protection and renewable energy','Power electronics, PID control and transducers'] if s['slug']=='electrical-electronics-engineering' else ['Analog modulation and envelope detection','Pulse modulation and digital baseband transmission','Digital passband modulation schemes','Antenna radiation patterns and microwave propagation','Optical fiber communication and optoelectronics','Digital signal processing and Shannon capacity limits'] if s['slug']=='electronics-communication' else ['Solid mechanics and materials testing','Fluid mechanics and hydraulic machinery','Thermodynamics and heat transfer','Dynamics, kinematics and mechanical vibrations','Machine design, tribology and manufacturing metrology','Mechatronics, control systems and industrial HVAC'] if s['slug']=='mechanical-engineering' else ['Yarn manufacturing and fiber science','Fabric manufacturing and structural mechanics','Textile chemical wet processing and dyeing','Fabric comfort and physical testing','Textile tribology and surface durability','Technical textiles, nonwovens and color science'] if s['slug']=='textile-engineering' else ['Site-grid and geophysical survey','Lithic technology and ceramic petrography','Pyrotechnology and archaeomagnetic dating','Bioarchaeology, osteometry and paleodiet isotopes','Geoarchaeological sediment analysis and micro-artifacts'] if s['slug']=='archaeology' else ['Fluvial geomorphology and channel hydraulics','Meteorology, microclimatology and radiation balance','Biogeography and hillslope soil hydrology','Coastal morphodynamics and shallow-water waves','Quantitative spatial analysis and thermal remote sensing'] if s['slug']=='geography' else s['examples']
  for i,topic in enumerate(future_topics,1):body+='<article class="topic-card"><span class="eyebrow">TOPIC '+str(i).zfill(2)+' · PLANNED</span><h3>'+esc(topic)+'</h3><p>Theory, practical method, observations and analysis will be developed together for this topic.</p></article>'
  body+='</div>'+how_it_works()+'<div class="subject-bottom"><a class="back-link" href="/#subjects">← Browse all subjects</a></div></main>'+footer()+'</div><script src="/lab-search.js"></script></body></html>'
  target=out/path.strip('/')/'index.html';target.parent.mkdir(parents=True,exist_ok=True);target.write_text(body)
 return sitemap
